-- 207: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 5.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_207_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_207_guard;
INSERT INTO _migration_207_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_017' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_4' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should guide the orientation of a long strap pattern on a hide?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The outer outline of the hide without reference to backbone or flank zones","B. The intended load together with the direction of stretch and the location of defects","C. The shortest route across the belly because that zone normally stretches most easily","D. The direction that produces the brightest colour even if the fibres elongate under load"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A strap carries repeated lengthwise load, so the maker aligns it through firm sound material while accounting for stretch direction, scars and economical yield. Therefore the correct answer is B: The intended load together with the direction of stretch and the location of defects.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_017' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_207_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_018' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_4' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What pattern function does a gusset perform in a leather bag?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It serves as a removable cutting guide after the bag has been stitched","B. It joins major panels at a planned distance to create side or base depth","C. It replaces the front panel with a folded decorative strip","D. It mainly reinforces the handle attachment without changing internal volume"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A gusset is drafted as a side or base component whose length, width and seam allowances control the bag volume and the fit between the main panels. Therefore the correct answer is B: It joins major panels at a planned distance to create side or base depth.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_018' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_207_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_019' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_4' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the value of making a card prototype before cutting expensive leather?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It fixes the final dimensions even when the closure and hardware later change","B. It reveals proportion, fold, fit and assembly problems at low cost","C. It proves that leather thickness and stiffness will have no effect on construction","D. It provides a finished surface sample for judging dye absorption on the leather"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A mock-up tests geometry and construction sequence before valuable material is cut, allowing pattern corrections while acknowledging that leather thickness still needs separate allowance. Therefore the correct answer is B: It reveals proportion, fold, fit and assembly problems at low cost.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_019' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_207_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_020' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_4' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How can a mirrored pattern piece be developed accurately from a centre line?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fold the pattern on the centre line and cut or trace both halves from the same outline","B. Add a wider seam allowance to one side to correct small drawing differences","C. Measure each half independently from its nearest outside edge","D. Rotate one completed half around a corner point instead of the centre line"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Using the fold as a common datum duplicates one verified half on both sides, avoiding cumulative measurement differences that produce an asymmetric component. Therefore the correct answer is A: Fold the pattern on the centre line and cut or trace both halves from the same outline.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_020' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_017', 'topic_was_leatherwork_b004_4', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What should guide the orientation of a long strap pattern on a hide?', 'multiple_choice', NULL, '["A. The outer outline of the hide without reference to backbone or flank zones","B. The intended load together with the direction of stretch and the location of defects","C. The shortest route across the belly because that zone normally stretches most easily","D. The direction that produces the brightest colour even if the fibres elongate under load"]', 'B', 'A strap carries repeated lengthwise load, so the maker aligns it through firm sound material while accounting for stretch direction, scars and economical yield. Therefore the correct answer is B: The intended load together with the direction of stretch and the location of defects.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_4', 'Identify', 'AO2', NULL, NULL, 'board_waec');
