INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_019', 'topic_was_leatherwork_b004_4', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What is the value of making a card prototype before cutting expensive leather?', 'multiple_choice', NULL, '["A. It fixes the final dimensions even when the closure and hardware later change","B. It reveals proportion, fold, fit and assembly problems at low cost","C. It proves that leather thickness and stiffness will have no effect on construction","D. It provides a finished surface sample for judging dye absorption on the leather"]', 'B', 'A mock-up tests geometry and construction sequence before valuable material is cut, allowing pattern corrections while acknowledging that leather thickness still needs separate allowance. Therefore the correct answer is B: It reveals proportion, fold, fit and assembly problems at low cost.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_4', 'Identify', 'AO1', NULL, NULL, 'board_waec');
